CREATE TABLE family(family_id INTEGER PRIMARY KEY AUTOINCREMENT,family_name TEXT NOT NULL);
CREATE TABLE genus(genus_id INTEGER PRIMARY KEY AUTOINCREMENT,family_id INTEGER REFERENCES family(family_id),genus_name TEXT NOT NULL);
CREATE TABLE conservation_status(status_id INTEGER PRIMARY KEY AUTOINCREMENT,status_name TEXT NOT NULL);
CREATE TABLE species(species_id INTEGER PRIMARY KEY AUTOINCREMENT,scientific_name TEXT NOT NULL,common_name TEXT,genus_id INTEGER REFERENCES genus(genus_id),status_id INTEGER REFERENCES conservation_status(status_id),description TEXT,rbac_data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(rbac_data)),registered_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE rbac_species_visibility(species_id INTEGER PRIMARY KEY REFERENCES species(species_id) ON DELETE CASCADE,visibility TEXT NOT NULL CHECK(visibility IN ('public','internal','protected')));
CREATE TABLE plant_record(plant_id INTEGER PRIMARY KEY AUTOINCREMENT,species_id INTEGER NOT NULL REFERENCES species(species_id),registered_subject TEXT NOT NULL,rbac_status TEXT NOT NULL DEFAULT 'Pending Review' CHECK(rbac_status IN ('Pending Review','Approved','Rejected','Flagged','Correction Required')),qr_token TEXT NOT NULL UNIQUE,registered_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE plant_location(location_id INTEGER PRIMARY KEY AUTOINCREMENT,plant_id INTEGER NOT NULL REFERENCES plant_record(plant_id),latitude REAL NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy_m REAL CHECK(accuracy_m>=0),recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE plant_observation(id TEXT PRIMARY KEY NOT NULL,plant_id INTEGER NOT NULL REFERENCES plant_record(plant_id),owner_subject TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Draft','Pending Review','Approved','Rejected','Flagged','Correction Required')),content TEXT NOT NULL CHECK(json_valid(content)),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),client_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(owner_subject,client_key));
CREATE TABLE observation_review(id TEXT PRIMARY KEY NOT NULL,observation_id TEXT NOT NULL REFERENCES plant_observation(id),reviewer_subject TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('Approved','Rejected','Flagged','Correction Required')),comment TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE plant_asset(id TEXT PRIMARY KEY NOT NULL,species_id INTEGER REFERENCES species(species_id),plant_id INTEGER REFERENCES plant_record(plant_id),owner_subject TEXT NOT NULL,client_key TEXT NOT NULL,observation_id TEXT REFERENCES plant_observation(id),approved INTEGER NOT NULL DEFAULT 0 CHECK(approved IN (0,1)),content_type TEXT NOT NULL,content BLOB NOT NULL CHECK(length(content)<=4194304),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(owner_subject,client_key),CHECK((species_id IS NULL)!=(plant_id IS NULL)));
CREATE TABLE iot_device(id TEXT PRIMARY KEY NOT NULL,name TEXT NOT NULL,plant_id INTEGER REFERENCES plant_record(plant_id),key_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')),thresholds TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(thresholds)),last_seen TEXT);
CREATE TABLE sensor_reading(id TEXT PRIMARY KEY NOT NULL,device_id TEXT NOT NULL REFERENCES iot_device(id),"values" TEXT NOT NULL CHECK(json_valid("values")),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE threat_alert_history(id TEXT PRIMARY KEY NOT NULL,device_id TEXT NOT NULL REFERENCES iot_device(id),reading_id TEXT NOT NULL REFERENCES sensor_reading(id),metric TEXT NOT NULL,value REAL NOT NULL,status TEXT NOT NULL DEFAULT 'New' CHECK(status IN ('New','Reviewing','Resolved')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE threat_response(id TEXT PRIMARY KEY NOT NULL,alert_id TEXT NOT NULL REFERENCES threat_alert_history(id),officer_subject TEXT NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Reviewing','Resolved')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE business_audit(id TEXT PRIMARY KEY NOT NULL,actor_subject TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX observation_owner_idx ON plant_observation(owner_subject);
CREATE INDEX reading_device_time_idx ON sensor_reading(device_id,created_at DESC);
CREATE INDEX location_plant_idx ON plant_location(plant_id,recorded_at DESC);
CREATE INDEX observation_plant_idx ON plant_observation(plant_id,status,updated_at DESC);
